diff --git a/internal/hosted/agent/loop_test.go b/internal/hosted/agent/loop_test.go
index 1db5b9a..4f4d2bc 100644
--- a/internal/hosted/agent/loop_test.go
+++ b/internal/hosted/agent/loop_test.go
@@ -274,3 +274,56 @@ func TestEstimateTokensRoundsUpAndOverestimates(t *testing.T) {
 		t.Fatalf("estimates: %d %d %d", EstimateTokens("abc"), EstimateTokens("abcd"), EstimateTokens(strings.Repeat("x", 3000)))
 	}
 }
+
+type flaggedThenOK struct {
+	calls  int
+	failN  int
+	detail string
+}
+
+func (f *flaggedThenOK) Complete(context.Context, llm.Request) (llm.Response, error) {
+	f.calls++
+	if f.calls <= f.failN {
+		return llm.Response{}, llm.ProviderError{ProviderName: "openai", StatusCode: 400, Detail: f.detail}
+	}
+	return llm.Response{Text: "ok", Usage: llm.Usage{InputTokens: 10, OutputTokens: 5}}, nil
+}
+
+const flaggedDetail = "Invalid prompt: your prompt was flagged as potentially violating our usage policy."
+
+func policyModel(client Completer, meter *Meter) Model {
+	return Model{Client: client, Name: "m", MaxOutputTokens: 100, Meter: meter, PolicyRetryWait: time.Millisecond, ContentionWait: time.Millisecond,
+		Price: llm.Price{InputMicrousdPerMillion: 1_000_000, OutputMicrousdPerMillion: 1_000_000}}
+}
+
+func policyBudget() Budget {
+	return Budget{MaxInputTokens: 10_000, MaxOutputTokens: 10_000, MaxCostMicrousd: 10_000_000, MaxModelCalls: 10, MaxToolCallsPerAgent: 3, WallTime: time.Minute}
+}
+
+func TestModelRetriesOnePolicyRejectionAndChargesBothCalls(t *testing.T) {
+	meter := NewMeter(policyBudget(), time.Now(), nil)
+	client := &flaggedThenOK{failN: 1, detail: flaggedDetail}
+	text, err := policyModel(client, meter).Call(context.Background(), "g", "sub-agent", Prompt{System: "s", User: "u"})
+	if err != nil || text != "ok" || client.calls != 2 {
+		t.Fatalf("text=%q err=%v calls=%d", text, err, client.calls)
+	}
+	if spend := meter.Spend(); spend.ModelCalls != 2 {
+		t.Fatalf("both attempts must be metered: %#v", spend)
+	}
+}
+
+func TestModelRetriesPolicyRejectionOnlyOnce(t *testing.T) {
+	client := &flaggedThenOK{failN: 5, detail: flaggedDetail}
+	_, err := policyModel(client, NewMeter(policyBudget(), time.Now(), nil)).Call(context.Background(), "g", "sub-agent", Prompt{System: "s", User: "u"})
+	if err == nil || client.calls != 2 {
+		t.Fatalf("err=%v calls=%d: want a failure after exactly two attempts", err, client.calls)
+	}
+}
+
+func TestModelDoesNotRetryOtherBadRequests(t *testing.T) {
+	client := &flaggedThenOK{failN: 5, detail: "The model `nope` does not exist"}
+	_, err := policyModel(client, NewMeter(policyBudget(), time.Now(), nil)).Call(context.Background(), "g", "sub-agent", Prompt{System: "s", User: "u"})
+	if err == nil || client.calls != 1 {
+		t.Fatalf("err=%v calls=%d: a real 400 must not be retried", err, client.calls)
+	}
+}

diff --git a/internal/hosted/agent/model.go b/internal/hosted/agent/model.go
index 340af66..b2015f3 100644
--- a/internal/hosted/agent/model.go
+++ b/internal/hosted/agent/model.go
@@ -4,6 +4,8 @@ import (
 	"context"
 	"errors"
 	"fmt"
+	"net/http"
+	"strings"
 	"time"

 	"px1/internal/hosted/llm"
@@ -29,6 +31,9 @@ type Model struct {
 	// ContentionWait is how long to wait before retrying a reservation that
 	// other in-flight calls are holding. Defaults to 50ms.
 	ContentionWait time.Duration
+	// PolicyRetryWait is how long to wait before the one retry of a call the
+	// provider's safety filter rejected. Defaults to 2s.
+	PolicyRetryWait time.Duration
 }

 // EstimateTokens is a deliberately high estimate (three bytes per token) so a
@@ -51,6 +56,38 @@ func ActualCost(price llm.Price, usage llm.Usage) int64 {
 // a provider may bill a request it did not complete; this can undercount a
 // call that timed out after generating, and the real bill is authoritative.
 func (m Model) Call(ctx context.Context, agent, role string, prompt Prompt) (string, error) {
+	text, err := m.callOnce(ctx, agent, role, prompt)
+	if !isPolicyRejection(err) {
+		return text, err
+	}
+	// The provider's safety filter is not deterministic: the same request
+	// has been rejected once and accepted on the next try. Retry exactly once,
+	// as a new metered call, so the retry is charged and bounded like any other.
+	wait := m.PolicyRetryWait
+	if wait <= 0 {
+		wait = 2 * time.Second
+	}
+	select {
+	case <-ctx.Done():
+		return "", err
+	case <-time.After(wait):
+	}
+	return m.callOnce(ctx, agent, role, prompt)
+}
+
+// isPolicyRejection recognizes the provider's usage-policy rejection of a
+// prompt: a 400 whose message says the prompt was flagged. Other 400s, such as
+// an unknown model, are real errors and are never retried.
+func isPolicyRejection(err error) bool {
+	var providerErr llm.ProviderError
+	if !errors.As(err, &providerErr) || providerErr.StatusCode != http.StatusBadRequest {
+		return false
+	}
+	detail := strings.ToLower(providerErr.Detail)
+	return strings.Contains(detail, "flagged") && strings.Contains(detail, "usage policy")
+}
+
+func (m Model) callOnce(ctx context.Context, agent, role string, prompt Prompt) (string, error) {
 	if m.Client == nil || m.Meter == nil || m.MaxOutputTokens <= 0 || m.Name == "" {
 		return "", errors.New("model client, meter, model name, and output limit are required")
 	}
